class TestContention:
    """Multi-threaded contention and resolution."""

    def test_contention_resolution(self) -> None:
        lock = IdentityLock()
        results: List[str] = []

        def worker(worker_id: int) -> None:
            for _ in range(10):
                lock.acquire(timeout=5.0)
                results.append(f"worker-{worker_id}")
                lock.release()

        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = [executor.submit(worker, i) for i in range(4)]
            for future in futures:
                future.result(timeout=10)

        # All operations should have completed without deadlock
        assert len(results) == 40

    def test_immediate_contention_multiple_threads(self) -> None:
        lock = IdentityLock()
        lock.acquire(timeout=0.0)

        errors: List[Exception] = []

        def contender() -> None:
            try:
                lock.acquire(timeout=0.0)
            except LockContentionError as e:
                errors.append(e)

        threads = [threading.Thread(target=contender) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(errors) == 10
        lock.release()

    def test_timeout_under_contention(self, controlled_clock) -> None:
        lock = IdentityLock(clock=controlled_clock)
        lock.acquire(timeout=0.0)

        errors: List[Exception] = []

        def contender() -> None:
            try:
                lock.acquire(timeout=0.1)
            except LockTimeoutError as e:
                errors.append(e)

        threads = [threading.Thread(target=contender) for _ in range(5)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(errors) == 5
        lock.release()


class TestStateConsistency:
    """Lock state remains consistent after exceptions."""

    def test_state_after_timeout_error(self, controlled_clock) -> None:
        lock = IdentityLock(clock=controlled_clock)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(1.0)

        with pytest.raises(LockTimeoutError):
            lock.acquire(timeout=0.1)

        # Lock should still be owned by the original thread
        assert lock.locked()
        lock.release()
        assert not lock.locked()

    def test_state_after_contention_error(self) -> None:
        lock = IdentityLock()
        lock.acquire(timeout=0.0)

        with pytest.raises(LockContentionError):
            lock.acquire(timeout=0.0)

        assert lock.locked()
        lock.release()
        assert not lock.locked()

    def test_release_after_failed_acquire(self, controlled_clock) -> None:
        lock = IdentityLock(clock=controlled_clock)
        lock.acquire(timeout=0.0)
        controlled_clock.advance(1.0)

        with pytest.raises(LockTimeoutError):
            lock.acquire(timeout=0.1)

        # Original owner can still release
        lock.release()
        assert not lock.locked()


